#!/usr/bin/env python3
"""cell/live-cell-track — auto-generated run.py (archetype=omics_scrna).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "omics_scrna"
BRAIN = "cell"
SKILL = "live-cell-track"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'tracks_csv': 'out/tracks.csv', 'lineage_tree_json': 'out/lineage_tree.json', 'mitotic_events_csv': 'out/mitotic_events.csv', 'n_tracks': 50, 'n_mitoses': 12, 'lineage_accuracy': 0.94, 'passed_sanity': True})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """Live cell tracking 简化版:逐帧 regionprops 取 centroid + greedy nearest-neighbor 匹配。
    host_env=PRAXIS-Cell(无 trackpy/btrack,用 skimage + numpy 简化)。
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    masks_tif = payload.get("masks_tif") or payload.get("masks_zstack")
    max_dist = float(payload.get("max_link_distance_px", 20))
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="track_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "skimage + greedy NN", "max_dist_px": max_dist, "out_dir": out_dir}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL,
                "n_tracks": 0, "n_mitoses": 0,
                "lineage_accuracy": 0.0, "lineage_tree_json": "",
                "mitotic_events_csv": "", "passed_sanity": True,
                "diagnostics": {**diagnostics, "dry": True}}
    if not masks_tif or not _os.path.isfile(masks_tif):
        return {"ok": False, "error": "需要 masks_tif (T×H×W mask)", "diagnostics": diagnostics}
    track_csv = _os.path.join(out_dir, "tracks.csv")
    script = (
        "import json, sys, os, csv, numpy as np, tifffile\n"
        "from skimage.measure import regionprops\n"
        f"masks = tifffile.imread({masks_tif!r})\n"
        f"max_d = {max_dist}; out_csv = {track_csv!r}\n"
        f"os.makedirs({out_dir!r}, exist_ok=True)\n"
        "if masks.ndim != 3: print(json.dumps({'__err':'masks 必须 T×H×W'})); sys.exit(1)\n"
        "next_tid = 1; current = {}  # mask_label -> tid (本帧)\n"
        "tracks = []\n"
        "for t in range(masks.shape[0]):\n"
        "    props = regionprops(masks[t])\n"
        "    new_current = {}\n"
        "    used = set()\n"
        "    for p in props:\n"
        "        cy, cx = p.centroid\n"
        "        best_tid, best_dist = None, max_d\n"
        "        for lab, tid in current.items():\n"
        "            # last centroid\n"
        "            last = [r for r in tracks if r['tid'] == tid and r['t'] == t-1]\n"
        "            if not last: continue\n"
        "            dy = cy - last[-1]['y']; dx = cx - last[-1]['x']\n"
        "            d = (dy*dy+dx*dx)**0.5\n"
        "            if d < best_dist and tid not in used:\n"
        "                best_dist, best_tid = d, tid\n"
        "        if best_tid is None:\n"
        "            best_tid = next_tid; next_tid += 1\n"
        "        used.add(best_tid)\n"
        "        new_current[p.label] = best_tid\n"
        "        tracks.append({'t': t, 'tid': best_tid, 'mask_label': int(p.label), 'y': float(cy), 'x': float(cx), 'area': int(p.area)})\n"
        "    current = new_current\n"
        "with open(out_csv, 'w') as fh:\n"
        "    w = csv.DictWriter(fh, fieldnames=['t','tid','mask_label','y','x','area']); w.writeheader()\n"
        "    for r in tracks: w.writerow(r)\n"
        "n_tracks = len({r['tid'] for r in tracks})\n"
        "json.dump({'tracks_csv': out_csv, 'n_tracks': n_tracks,\n"
        "           'n_frames': int(masks.shape[0])}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=int(payload.get("timeout_s", 1800)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "tracking 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL,
            "n_tracks": parsed.get("n_tracks", 0), "n_mitoses": 0,
            "lineage_accuracy": 0.0, "lineage_tree_json": "",
            "mitotic_events_csv": "", "passed_sanity": parsed.get("n_tracks", 0) > 0,
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, **parsed}}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
